const defaultRequest = {
  task_id: 'WF-BACKLOG-RECOMMEND-001',
  request: 'Recomendar siguiente trabajo del backlog',
  requested_by: 'human',
  available_time: 'unknown',
  preferred_mode: 'any',
  max_options: 3,
  respect_wip: true,
};

const incoming = items && items[0] && items[0].json ? items[0].json : {};
const request = Object.keys(incoming).length ? { ...defaultRequest, ...incoming } : defaultRequest;
const text = `${request.request || ''} ${request.objective || ''}`.toLowerCase();

let primaryAgent = 'AGENT-BKL-001';
let reason = 'La solicitud requiere revisar tablero, prioridad, WIP y recomendar siguiente trabajo.';
let workflow = 'WF-BACKLOG-RECOMMEND-001';

if (text.includes('refinar') || text.includes('validacion') || text.includes('validación') || text.includes('criterios')) {
  primaryAgent = 'AGENT-REF-001';
  reason = 'La solicitud requiere refinamiento, criterios, tareas, V&V y evidencia esperada.';
  workflow = 'WF-REFINE-STORY-001';
}

if (text.includes('arquitectura') || text.includes('adr') || text.includes('decision') || text.includes('decisión')) {
  primaryAgent = 'AGENT-ARCH-001';
  reason = 'La solicitud requiere revision arquitectonica o decision tecnica transversal.';
  workflow = 'WF-ARCH-REVIEW-001';
}

if (text.includes('mercado') || text.includes('keyword') || text.includes('demanda')) {
  primaryAgent = 'AGENT-MKT-001';
  reason = 'La solicitud requiere inteligencia de mercado y control de claims.';
  workflow = 'WF-MARKET-INTEL-001';
}

const centralRepo = '/home/chuchosam/Documentos/github/invernadero-central';
const sensorRepo = '/home/chuchosam/Documentos/github/invernadero/green-house';
const webRepo = '/home/chuchosam/Documentos/github/agrotechia-web-ui';

return [{
  json: {
    task_id: request.task_id || workflow,
    agent_id: 'AGENT-ORCH-001',
    status: 'SUCCESS',
    summary: 'Solicitud clasificada y enrutada por Orchestrator. Esta version usa Function node para compatibilidad amplia con n8n.',
    route: {
      workflow,
      primary_agent: primaryAgent,
      supporting_agents: ['AGENT-KNOW-001', 'AGENT-REV-001'],
      authority: 'A1',
      review_required: true,
      reason,
    },
    repositories: {
      central: centralRepo,
      sensors_edge_data: sensorRepo,
      web: webRepo,
    },
    required_context_refs: [
      `${centralRepo}/agents/shared/project-rules.yaml`,
      `${centralRepo}/agents/shared/contracts.yaml`,
      `${centralRepo}/agents/registry.yaml`,
      `${centralRepo}/agents/orchestrator/agent.yaml`,
      `${centralRepo}/project/kanban/board.yaml`,
      `${centralRepo}/project/agents-operating-model.md`,
      `${centralRepo}/project/roles/expert-role-catalog.yaml`,
      `${centralRepo}/project/backlog/master-backlog.yaml`,
    ],
    constraints: [
      'No modificar HU congeladas.',
      'No mover estados sin aprobacion humana.',
      'No marcar DONE sin evidencia.',
      'No ejecutar compras, control fisico ni despliegues criticos sin aprobacion humana.',
      'Hacer una sola pregunta al humano por turno.'
    ],
    next_action: primaryAgent === 'AGENT-BKL-001'
      ? 'Crear/conectar el Backlog Agent para leer project/kanban/board.yaml y devolver maximo 3 opciones al humano.'
      : 'Construir contexto minimo para el agente especializado y producir borrador revisable.',
    human_question: primaryAgent === 'AGENT-BKL-001'
      ? 'Cual opcion quieres tomar ahora?'
      : 'Confirmas que quieres refinar esta solicitud con el agente especializado?',
  }
}];
